const sources = [$json.body, $json.query, $json.params, $json.headers, $json];

function normalizeObject(value) {
  if (!value) return {};
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' ? parsed : {};
    } catch {
      return {};
    }
  }
  return typeof value === 'object' ? value : {};
}

function cleanString(value) {
  return String(value || '').trim();
}

function firstNonEmpty(values) {
  for (const value of values) {
    const cleaned = cleanString(value);
    if (cleaned) return cleaned;
  }
  return '';
}

function buildFullName(first, last) {
  return [cleanString(first), cleanString(last)].filter(Boolean).join(' ').trim();
}

function looksLikeFallbackContactName(value) {
  return /^Contact\s+\S+$/i.test(cleanString(value));
}

function looksLikeFallbackOpportunityName(value) {
  return /^Contact\s+\S+\s+-\s+Warm$/i.test(cleanString(value));
}

const normalizedSources = sources.map(normalizeObject);
const payload = Object.assign({}, ...normalizedSources);
const body = normalizeObject($json.body);
const contact = normalizeObject(payload.contact);

const contactId = firstNonEmpty([
  payload.contactId,
  payload.contactID,
  payload.contact_id,
  payload.contactid,
  payload.id,
  body.contactId,
  body.contactID,
  body.contact_id,
  body.contactid,
  body.id,
  contact.id,
  contact.contactId,
  contact.contact_id,
]);

if (!contactId) {
  throw new Error(`Missing contactId in webhook payload. Top-level keys: ${Object.keys($json || {}).join(', ')} | body keys: ${Object.keys(body || {}).join(', ')}`);
}

