  payload.contactName,
  payload.contact_name,
  body.contactName,
  body.contact_name,
  contact.name,
  payload.name,
  body.name,
  buildFullName(
    payload.firstName || payload.first_name || body.firstName || body.first_name || contact.firstName || contact.first_name,
    payload.lastName || payload.last_name || body.lastName || body.last_name || contact.lastName || contact.last_name,
  ),
]);

