  payload.tagName ||
  payload.addedTag ||
  payload.tag_added ||
  body.tag ||
  body.tagName ||
  body.addedTag ||
  body.tag_added ||
  ''
);

const allowedTags = new Set(['stage: mql', 'mql']);
if (tagRaw && !allowedTags.has(tagRaw.toLowerCase())) {
  return [{
    json: {
      status: 'ignored',
      reason: 'tag_not_mql',
      contactId,
      receivedTag: tagRaw,
    },
  }];
