};

const headers = {
  Authorization: `Bearer ${apiKey}`,
  Version: '2021-07-28',
  Accept: 'application/json',
  'Content-Type': 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (typeof this !== 'undefined' && this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP not available in Code node runtime.');
}

function opportunityId(opp) {
  return opp?.id || opp?._id || '';
}

function pipelineIdOf(opp) {
  return opp?.pipelineId || opp?.pipeline_id || opp?.pipeline?.id || opp?.pipeline?._id || '';
}

function stageIdOf(opp) {
  return opp?.pipelineStageId || opp?.pipeline_stage_id || opp?.pipelineStage?.id || opp?.pipelineStage?._id || '';
}

function timestampOf(opp) {
  const raw = opp?.updatedAt || opp?.dateUpdated || opp?.createdAt || opp?.dateAdded || opp?.created_at || 0;
  const ts = Date.parse(raw);
  return Number.isFinite(ts) ? ts : 0;
}

function extractOpportunities(data) {
  if (Array.isArray(data?.opportunities)) return data.opportunities;
  if (Array.isArray(data?.data?.opportunities)) return data.data.opportunities;
  if (Array.isArray(data?.data)) return data.data;
  if (Array.isArray(data)) return data;
  return [];
}

function extractContactRecord(data) {
  return normalizeObject(data?.contact || data?.data?.contact || data?.data || data);
}

