let contactLookupError = '';

if (!resolvedContactName || looksLikeFallbackContactName(resolvedContactName)) {
  contactLookupStatus = 'attempted';
  try {
    const contactResult = await doHttpRequest.call(this, {
      method: 'GET',
      url: `${baseUrl}/contacts/${encodeURIComponent(contactId)}`,
      headers,
      json: true,
    });
    const liveContact = extractContactRecord(contactResult);
    const fetchedContactName = firstNonEmpty([
      liveContact.name,
      buildFullName(liveContact.firstName || liveContact.first_name, liveContact.lastName || liveContact.last_name),
      buildFullName(liveContact.first_name, liveContact.last_name),
    ]);

    if (fetchedContactName) {
      resolvedContactName = fetchedContactName;
      contactNameSource = 'ghl_contact_lookup';
      contactLookupStatus = 'resolved';
    } else {
      contactLookupStatus = 'empty_name';
    }
  } catch (err) {
    const code = err?.statusCode || err?.httpCode || 500;
    const bodyText = err?.response?.body || err?.message || err;
    contactLookupStatus = 'error';
    contactLookupError = `${code} ${JSON.stringify(bodyText)}`;
  }
}

const finalContactName = resolvedContactName || `Contact ${contactId}`;

