  const body = err?.response?.body || err?.message || err;
  throw new Error(`Failed to search opportunities: ${code} ${JSON.stringify(body)}`);
}

const opportunities = extractOpportunities(searchResult).sort((a, b) => timestampOf(b) - timestampOf(a));
