    });
  } catch (err) {
    const code = err?.statusCode || err?.httpCode || 500;
    const bodyText = err?.response?.body || err?.message || err;
    throw new Error(`Failed to create opportunity: ${code} ${JSON.stringify(bodyText)}`);
  }

  return [{
    json: {
      status: 'created',
      contactId,
      contactName: finalContactName,
      contactNameSource,
      contactLookupStatus,
      contactLookupError,
      opportunityId: opportunityId(created?.opportunity || created?.data || created),
      opportunityName: desiredName,
      pipelineId: ids.warmPipelineId,
      pipelineStageId: ids.warmQualifiedStageId,
    },
  }];
}

if (pipelineIdOf(existingOpportunity) === ids.warmPipelineId && stageIdOf(existingOpportunity) === ids.warmQualifiedStageId) {
  if (!shouldUpdateOpportunityName) {
    return [{
      json: {
        status: 'noop',
        reason: 'already_at_target_stage',
        contactId,
        contactName: finalContactName,
        contactNameSource,
        contactLookupStatus,
        contactLookupError,
        opportunityId: opportunityId(existingOpportunity),
      },
    }];
  }

  try {
    await doHttpRequest.call(this, {
      method: 'PUT',
      url: `${baseUrl}/opportunities/${encodeURIComponent(opportunityId(existingOpportunity))}`,
      headers,
      body: {
        name: desiredName,
      },
      json: true,
    });
  } catch (err) {
    const code = err?.statusCode || err?.httpCode || 500;
    const bodyText = err?.response?.body || err?.message || err;
    throw new Error(`Failed to rename opportunity at target stage: ${code} ${JSON.stringify(bodyText)}`);
  }

  return [{
    json: {
      status: 'renamed',
      reason: 'updated_placeholder_name',
      contactId,
      contactName: finalContactName,
      contactNameSource,
      contactLookupStatus,
      contactLookupError,
      opportunityId: opportunityId(existingOpportunity),
      opportunityName: desiredName,
      pipelineId: ids.warmPipelineId,
      pipelineStageId: ids.warmQualifiedStageId,
    },
  }];
}

try {
  await doHttpRequest.call(this, {
    method: 'PUT',
    url: `${baseUrl}/opportunities/${encodeURIComponent(opportunityId(existingOpportunity))}`,
    headers,
    body: {
      pipelineId: ids.warmPipelineId,
      pipelineStageId: ids.warmQualifiedStageId,
      ...(shouldUpdateOpportunityName ? { name: desiredName } : {}),
    },
    json: true,
  });
} catch (err) {
  const code = err?.statusCode || err?.httpCode || 500;
